/**
 * Score the detector on seeded synthetic logs (T5). The detector sees only the
 * CSV and approvals; ground truth stays here. Metrics are per incident:
 *   precision = alerts touching a real incident / all alerts
 *   recall    = incidents with at least one alert / all incidents
 *   time-to-alert = alert detection time (receipt of the triggering event)
 *                   − receipt of the incident's first event
 *   false alerts per 1,000 benign events = alerts touching no incident event
 *                   / benign events × 1000
 */

                           
               
                 
                 
                    
                 
                    
                    
                   
                    
                 
             
                               
                             
                   
                              
  

const median = (xs          ) => {
  if (xs.length === 0) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
const round = (x        ) => Math.round(x * 1000) / 1000;

export function evaluate(opts                                 )              {
  const data = generate(opts);
  const events = parseEventsCsv(data.csv);
  const report = detect(events, parseApprovals(data.approvals), loadPolicy());
  const receivedAt = new Map                ();
  for (const line of data.csv.trimEnd().split("\n").slice(1)) {
    const [id, , received] = line.split(",");
    receivedAt.set(id, Date.parse(received));
  }

  let tp = 0;
  const falseRules           = [];
  const firstAlertFor = new Map                ();
  for (const a of report.alerts) {
    const hit = new Set(a.event_ids.map((id) => data.truth.get(id)).filter((x)              => !!x));
    if (hit.size === 0) {
      falseRules.push(a.rule);
      continue;
    }
    tp++;
    const at = Date.parse(a.detected_at_received_utc);
    for (const inc of hit) firstAlertFor.set(inc, Math.min(firstAlertFor.get(inc) ?? Infinity, at));
  }
  const tta           = [];
  const missed           = [];
  for (const inc of data.incidents) {
    const at = firstAlertFor.get(inc.id);
    if (at === undefined) {
      missed.push(`${inc.id}:${inc.kind}`);
      continue;
    }
    const first = Math.min(...inc.event_ids.map((id) => receivedAt.get(id) ?? Infinity));
    tta.push(Math.max(0, at - first));
  }
  const alerts = report.alerts.length;
  const precision = alerts ? tp / alerts : 1;
  const recall = data.incidents.length ? (data.incidents.length - missed.length) / data.incidents.length : 1;
  const f1 = precision + recall ? (2 * precision * recall) / (precision + recall) : 0;
  const benign = data.events - data.truth.size;
  return {
    seed: opts.seed,
    events: data.events,
    benign,
    incidents: data.incidents.length,
    alerts,
    tp_alerts: tp,
    fp_alerts: alerts - tp,
    detected: data.incidents.length - missed.length,
    precision: round(precision),
    recall: round(recall),
    f1: round(f1),
    median_tta_ms: median(tta),
    fp_per_1000_benign: round(((alerts - tp) / benign) * 1000),
    missed,
    false_alert_rules: falseRules,
  };
}

export function evaluateSeeds(seeds          , opts               = {}) {
  const per = seeds.map((seed) => evaluate({ ...opts, seed }));
  const sum = (k                                                                                       ) =>
    per.reduce((a, m) => a + m[k], 0);
  const precision = sum("alerts") ? sum("tp_alerts") / sum("alerts") : 1;
  const recall = sum("detected") / sum("incidents");
  return {
    per_seed: per,
    aggregate: {
      events: sum("events"),
      benign_events: sum("benign"),
      incidents: sum("incidents"),
      alerts: sum("alerts"),
      precision: round(precision),
      recall: round(recall),
      f1: round((2 * precision * recall) / (precision + recall || 1)),
      median_time_to_alert_ms: median(per.map((m) => m.median_tta_ms).filter((x)              => x !== null)),
      false_alerts_per_1000_benign: round((sum("fp_alerts") / sum("benign")) * 1000),
    },
  };
}

